static int is_empty_or_comment(char *line)
{
        unsigned int i;

        for (i = 0; i < strlen(line); i++) {
                if (line[i] == ';')
                        return 1;
                if (line[i] == '#')
                        return 1;
                if (!isspace((int) line[i]) && !iscntrl((int) line[i]))
                        return 0;
        }

        return 1;
}

